{
  "reference_answer": "Honestly, I'd rather live in a big city, mainly because of the sheer convenience. Everything's within reach — late-night supermarkets, decent public transport, and a huge range of restaurants. I also like the fact that there's always something going on, whether it's a concert or a small exhibition. That said, I can see the downside: it's noisy, rent is sky-high, and you rarely get any peace. So for me, the trade-off is worth it while I'm young and busy, but I wouldn't rule out moving somewhere quieter later on, maybe once I want a bit more space and a slower pace of life.",
  "reference_angle_summary": "独立主线：以“便利与热闹 vs 噪音与高房租”的权衡为核心，并加入随时间可能改变选择的反思；示例不代表用户经历。",
  "takeaway_expressions": [
    {
      "expression": "within reach",
      "meaning_zh": "触手可及；很容易获得",
      "why_useful": "描述城市便利、资源可及性时非常自然，比只说 convenient 更具体。",
      "example": "In a big city, good hospitals and schools are usually within reach.",
      "usage_note": "常与 everything / amenities / services 搭配。"
    },
    {
      "expression": "the trade-off is worth it",
      "meaning_zh": "这种取舍是值得的",
      "why_useful": "表达优缺点权衡时高频、口语化，适合 Part 3 讨论类问题。",
      "example": "The commute is long, but the trade-off is worth it for a better job.",
      "usage_note": "trade-off 可数，前面常加 the。"
    },
    {
      "expression": "I wouldn't rule out",
      "meaning_zh": "我不会排除……的可能性",
      "why_useful": "表达未来可能性、保留态度时很自然，避免绝对化。",
      "example": "I wouldn't rule out moving abroad for a year or two.",
      "usage_note": "后接名词或动名词，语气比 maybe 更成熟。"
    }
  ]
}

